/* @autogenerated */
import { ObservedSourceRepository } from 'app/features/observe/observed-source/repository/observed-source-repository.service';
import { normalizeHeader } from 'app/shared/toolkit/entity-import/column-match';
import {
  OBSERVED_ISSUE_EXCEL_COLUMNS,
  OBSERVED_ISSUE_EXCEL_SENSITIVE,
} from 'app/features/observe/observed-issue/model/observed-issue-excel-columns';
import { ObservedIssue } from 'app/features/observe/observed-issue/model/observed-issue.model';
import { take, map } from 'rxjs';
import { ObservedIssueRepository } from 'app/features/observe/observed-issue/repository/observed-issue-repository.service';
import { BaseImportAction } from 'app/shared/toolkit/action/base-import-action';
import { ImportDefinition } from 'app/shared/toolkit/entity-import/entity-import.model';
import { Component, inject } from '@angular/core';

/** Candidatos que pide cada búsqueda: el filtro puede no ser exacto y se comprueba aquí. */
const LOOKUP_LIMIT = 50;

@Component({
  selector: 'observed-issue-view-import-action',
  standalone: false,
  templateUrl: './observed-issue-view-import-action.component.html',
})
export class ObservedIssueViewImportActionComponent extends BaseImportAction<ObservedIssue> {
  protected readonly scope = 'observe/observed-issue';
  protected readonly repository = inject(ObservedIssueRepository);
  private readonly originRepository = inject(ObservedSourceRepository);

  readonly definition: ImportDefinition<ObservedIssue> = {
    storageKey: 'observe.observed-issue',
    scope: this.scope,
    // Clave natural (índice único del modelo): una fila con los mismos valores actualiza el elemento
    keys: ['origin', 'fingerprint'],
    columns: OBSERVED_ISSUE_EXCEL_COLUMNS,
    sensitive: OBSERVED_ISSUE_EXCEL_SENSITIVE,
    // Campos que el backend solo cambia con sus acciones: se aplican tras crear o actualizar
    actions: {
      status: [
        { name: 'markResolved', value: 'resolved', run: (item) => this.repository.markResolved(item.uid) },
        { name: 'ignore', value: 'ignored', run: (item) => this.repository.ignore(item.uid) },
        { name: 'reopen', value: 'unresolved', run: (item) => this.repository.reopen(item.uid) },
      ],
    },
    references: {
      origin: {
        resolve: (text) =>
          this.originRepository.values({ search: text, limit: LOOKUP_LIMIT }).pipe(
            take(1),
            map((found) => {
              const wanted = normalizeHeader(text);
              const one = found.find(
                (candidate) => candidate.uid === text || normalizeHeader(candidate.code) === wanted,
              );
              return one ? { $ref: one.uid } : null;
            }),
          ),
      },
    },
    defaults: () => ({ kind: 'error', level: 'error', status: 'unresolved', count: 0, users: 0, tenants: 0 }),
    display: (values) => String(values.title ?? ''),
    target: {
      acl: () => this.repository.checkAcl(),
      find: (values) =>
        this.repository
          .values({
            origin: values.origin?.$ref ? [values.origin.$ref] : undefined,
            fingerprint: values.fingerprint,
            limit: LOOKUP_LIMIT,
          })
          .pipe(
            take(1),
            map((found) =>
              found.filter(
                (item) =>
                  (!values.origin?.$ref || item.origin?.$ref === values.origin.$ref) &&
                  item.fingerprint === values.fingerprint,
              ),
            ),
          ),
      add: (item) => this.repository.add(item),
      update: (item) => this.repository.update(item),
      context: this.repository.context(),
    },
  };
}
